import { clsx } from "clsx";
import React, { Component, createRef } from "react";

import {
  getDay,
  getMonth,
  getDate,
  newDate,
  isSameDay,
  isDayDisabled,
  isDayExcluded,
  isDayInRange,
  isEqual,
  isBefore,
  isAfter,
  getDayOfWeekCode,
  getStartOfWeek,
  formatDate,
  type DateFilterOptionsWithDisabled,
  type DateNumberType,
  type Locale,
  type HolidaysMap,
  KeyType,
} from "./date_utils";

interface DayProps extends Pick<
  DateFilterOptionsWithDisabled,
  | "minDate"
  | "maxDate"
  | "excludeDates"
  | "excludeDateIntervals"
  | "includeDateIntervals"
  | "includeDates"
  | "filterDate"
  | "disabled"
> {
  ariaLabelPrefixWhenEnabled?: string;
  ariaLabelPrefixWhenDisabled?: string;
  disabledKeyboardNavigation?: boolean;
  day: Date;
  dayClassName?: (date: Date) => string;
  highlightDates?: Map<string, string[]>;
  holidays?: HolidaysMap;
  inline?: boolean;
  shouldFocusDayInline?: boolean;
  month: number;
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  onMouseEnter?: React.MouseEventHandler<HTMLDivElement>;
  handleOnKeyDown?: React.KeyboardEventHandler<HTMLDivElement>;
  usePointerEvent?: boolean;
  preSelection?: Date | null;
  selected?: Date | null;
  selectingDate?: Date;
  selectsEnd?: boolean;
  selectsStart?: boolean;
  selectsRange?: boolean;
  showWeekPicker?: boolean;
  showWeekNumber?: boolean;
  selectsDisabledDaysInRange?: boolean;
  selectsMultiple?: boolean;
  selectedDates?: Date[];
  startDate?: Date | null;
  endDate?: Date | null;
  renderDayContents?: (day: number, date: Date) => React.ReactNode;
  containerRef?: React.RefObject<HTMLDivElement | null>;
  calendarStartDay?: DateNumberType;
  locale?: Locale;
  monthShowsDuplicateDaysEnd?: boolean;
  monthShowsDuplicateDaysStart?: boolean;
  swapRange?: boolean;
}

/**
 * `Day` is a React component that represents a single day in a date picker.
 * It handles the rendering and interaction of a day.
 *
 * @prop ariaLabelPrefixWhenEnabled - Aria label prefix when the day is enabled.
 * @prop ariaLabelPrefixWhenDisabled - Aria label prefix when the day is disabled.
 * @prop disabledKeyboardNavigation - Whether keyboard navigation is disabled.
 * @prop day - The day to be displayed.
 * @prop dayClassName - Function to customize the CSS class of the day.
 * @prop endDate - The end date in a range.
 * @prop highlightDates - Map of dates to be highlighted.
 * @prop holidays - Map of holiday dates.
 * @prop inline - Whether the date picker is inline.
 * @prop shouldFocusDayInline - Whether the day should be focused when date picker is inline.
 * @prop month - The month the day belongs to.
 * @prop onClick - Click event handler.
 * @prop onMouseEnter - Mouse enter event handler.
 * @prop handleOnKeyDown - Key down event handler.
 * @prop usePointerEvent - Whether to use pointer events.
 * @prop preSelection - The date that is currently selected.
 * @prop selected - The selected date.
 * @prop selectingDate - The date currently being selected.
 * @prop selectsEnd - Whether the day can be the end date in a range.
 * @prop selectsStart - Whether the day can be the start date in a range.
 * @prop selectsRange - Whether the day can be in a range.
 * @prop showWeekPicker - Whether to show week picker.
 * @prop showWeekNumber - Whether to show week numbers.
 * @prop selectsDisabledDaysInRange - Whether to select disabled days in a range.
 * @prop selectsMultiple - Whether to allow multiple date selection.
 * @prop selectedDates - Array of selected dates.
 * @prop startDate - The start date in a range.
 * @prop renderDayContents - Function to customize the rendering of the day's contents.
 * @prop containerRef - Ref for the container.
 * @prop excludeDates - Array of dates to be excluded.
 * @prop calendarStartDay - The start day of the week.
 * @prop locale - The locale object.
 * @prop monthShowsDuplicateDaysEnd - Whether to show duplicate days at the end of the month.
 * @prop monthShowsDuplicateDaysStart - Whether to show duplicate days at the start of the month.
 * @prop includeDates - Array of dates to be included.
 * @prop includeDateIntervals - Array of date intervals to be included.
 * @prop minDate - The minimum date that can be selected.
 * @prop maxDate - The maximum date that can be selected.
 *
 * @example
 * ```tsx
 * import React from 'react';
 * import Day from './day';
 *
 * function MyComponent() {
 *   const handleDayClick = (event) => {
 *     console.log('Day clicked', event);
 *   };
 *
 *   const handleDayMouseEnter = (event) => {
 *     console.log('Mouse entered day', event);
 *   };
 *
 *   const renderDayContents = (date) => {
 *     return <div>{date.getDate()}</div>;
 *   };
 *
 *   return (
 *     <Day
 *       day={new Date()}
 *       onClick={handleDayClick}
 *       onMouseEnter={handleDayMouseEnter}
 *       renderDayContents={renderDayContents}
 *     />
 *   );
 * }
 *
 * export default MyComponent;
 * ```
 */
export default class Day extends Component<DayProps> {
  componentDidMount() {
    this.handleFocusDay();
  }

  componentDidUpdate() {
    this.handleFocusDay();
  }

  dayEl = createRef<HTMLDivElement>();

  handleClick: DayProps["onClick"] = (event) => {
    if (!this.isDisabled() && this.props.onClick) {
      this.props.onClick(event);
    }
  };

  handleMouseEnter: DayProps["onMouseEnter"] = (event) => {
    if (!this.isDisabled() && this.props.onMouseEnter) {
      this.props.onMouseEnter(event);
    }
  };

  handleOnKeyDown: React.KeyboardEventHandler<HTMLDivElement> = (event) => {
    const eventKey = event.key;
    if (eventKey === KeyType.Space) {
      event.preventDefault();
      event.key = KeyType.Enter;
    }

    this.props.handleOnKeyDown?.(event);
  };

  isSameDay = (other: Date | null | undefined) =>
    isSameDay(this.props.day, other);

  isKeyboardSelected = () => {
    if (this.props.disabledKeyboardNavigation) {
      return false;
    }

    const isSelectedDate = this.props.selectsMultiple
      ? this.props.selectedDates?.some((date) => this.isSameDayOrWeek(date))
      : this.isSameDayOrWeek(this.props.selected);

    const isDisabled =
      this.props.preSelection && this.isDisabled(this.props.preSelection);

    return (
      !isSelectedDate &&
      this.isSameDayOrWeek(this.props.preSelection) &&
      !isDisabled
    );
  };

  isDisabled = (day = this.props.day) =>
    // Almost all props previously were passed as this.props w/o proper typing with prop-types
    // after the migration to TS i made it explicit
    isDayDisabled(day, {
      minDate: this.props.minDate,
      maxDate: this.props.maxDate,
      excludeDates: this.props.excludeDates,
      excludeDateIntervals: this.props.excludeDateIntervals,
      includeDateIntervals: this.props.includeDateIntervals,
      includeDates: this.props.includeDates,
      filterDate: this.props.filterDate,
      disabled: this.props.disabled,
    });

  isExcluded = () =>
    // Almost all props previously were passed as this.props w/o proper typing with prop-types
    // after the migration to TS i made it explicit
    isDayExcluded(this.props.day, {
      excludeDates: this.props.excludeDates,
      excludeDateIntervals: this.props.excludeDateIntervals,
    });

  isStartOfWeek = () =>
    isSameDay(
      this.props.day,
      getStartOfWeek(
        this.props.day,
        this.props.locale,
        this.props.calendarStartDay,
      ),
    );

  isSameWeek = (other?: Date | null) =>
    this.props.showWeekPicker &&
    isSameDay(
      other,
      getStartOfWeek(
        this.props.day,
        this.props.locale,
        this.props.calendarStartDay,
      ),
    );

  isSameDayOrWeek = (other?: Date | null) =>
    this.isSameDay(other) || this.isSameWeek(other);

  getHighLightedClass = () => {
    const { day, highlightDates } = this.props;

    if (!highlightDates) {
      return false;
    }

    // Looking for className in the Map of {'day string, 'className'}
    const dayStr = formatDate(day, "MM.dd.yyyy");
    return highlightDates.get(dayStr);
  };

  // Function to return the array containing className associated to the date

// Function to return the array containing className associated to the date
getHolidaysClass = () => {
  const { day, holidays } = this.props;
  if (!holidays) {
    // For type consistency no other reasons
    return [undefined];
  }
  const dayStr = formatDate(day, "MM.dd.yyyy");
  // Looking for className in the Map of {day string: {className, holidayName}}
  if (holidays.has(dayStr)) {
    return [holidays.get(dayStr)?.className];
  }

  // For type consistency no other reasons
  return [undefined];
};

isInRange = () => {
  const { day, startDate, endDate } = this.props;
  if (!startDate || !endDate) {
    return false;
  }
  return isDayInRange(day, startDate, endDate);
};

isInSelectingRange = () => {
  const {
    day,
    selectsStart,
    selectsEnd,
    selectsRange,
    selectsDisabledDaysInRange,
    startDate,
    swapRange,
    endDate,
  } = this.props;

  const selectingDate = this.props.selectingDate ?? this.props.preSelection;

  if (
    !(selectsStart || selectsEnd || selectsRange) ||
    !selectingDate ||
    (!selectsDisabledDaysInRange && this.isDisabled())
  ) {
    return false;
  }

  if (
    selectsStart &&
    endDate &&
    (isBefore(selectingDate, endDate) || isEqual(selectingDate, endDate))
  ) {
    return isDayInRange(day, selectingDate, endDate);
  }

  if (
    selectsEnd &&
    startDate &&
    (isAfter(selectingDate, startDate) || isEqual(selectingDate, startDate))
  ) {
    return isDayInRange(day, startDate, selectingDate);
  }

  if (selectsRange && startDate && !endDate) {
    if (isEqual(selectingDate, startDate)) {
      return isDayInRange(day, startDate, selectingDate);
    }

    if (isAfter(selectingDate, startDate)) {
      return isDayInRange(day, startDate, selectingDate);
    }

    if (swapRange && isBefore(selectingDate, startDate)) {
      return isDayInRange(day, selectingDate, startDate);
    }
  }

  return false;
};

isSelectingRangeStart = () => {
  if (!this.isInSelectingRange()) {
    return false;
  }

  const { day, startDate, selectsStart, swapRange, selectsRange } =
    this.props;
  const selectingDate = this.props.selectingDate ?? this.props.preSelection;

  if (selectsStart) {
    return isSameDay(day, selectingDate);
  }

  if (selectsRange && swapRange && startDate && selectingDate) {
    return isSameDay(
      day,
      isBefore(selectingDate, startDate) ? selectingDate : startDate,
    );
  }

  return isSameDay(day, startDate);
};

isSelectingRangeEnd = () => {
  if (!this.isInSelectingRange()) {
    return false;
  }

  const { day, endDate, selectsEnd, selectsRange, swapRange, startDate } =
    this.props;
  const selectingDate = this.props.selectingDate ?? this.props.preSelection;

  if (selectsEnd) {
    return isSameDay(day, selectingDate);
  }

  if (selectsRange && swapRange && startDate && selectingDate) {
    return isSameDay(
      day,
      isBefore(selectingDate, startDate) ? startDate : selectingDate,
    );
  }

  if (selectsRange) {
    return isSameDay(day, selectingDate);
  }

  return isSameDay(day, endDate);
};

isRangeStart = () => {
  const { day, startDate, endDate } = this.props;
  if (!startDate || !endDate) {
    return false;
  }
  return isSameDay(startDate, day);
};

isRangeEnd = () => {
  const { day, startDate, endDate } = this.props;
  if (!startDate || !endDate) {
    return false;
  }
  return isSameDay(endDate, day);
};

isWeekend = () => {
  const weekday = getDay(this.props.day);
  return weekday === 0 || weekday === 6;
};

isAfterMonth = () => {
  return (
    this.props.month !== undefined &&
    (this.props.month + 1) % 12 === getMonth(this.props.day)
  );
};

isBeforeMonth = () => {
  return (
    this.props.month !== undefined &&
    (getMonth(this.props.day) + 1) % 12 === this.props.month
  );
};

isCurrentDay = () => this.isSameDay(newDate());

isSelected = () => {
  if (this.props.selectsMultiple) {
    return this.props.selectedDates?.some((date) =>
      this.isSameDayOrWeek(date),
    );
  }
  return this.isSameDayOrWeek(this.props.selected);
};

getClassNames = (date: Date) => {
  const dayClassName = this.props.dayClassName
    ? this.props.dayClassName(date)
    : undefined;
  return clsx(
    "react-datepicker__day",
    dayClassName,
    "react-datepicker__day--" + getDayOfWeekCode(this.props.day),
    {
      "react-datepicker__day--disabled": this.isDisabled(),
      "react-datepicker__day--excluded": this.isExcluded(),
      "react-datepicker__day--selected": this.isSelected(),
      "react-datepicker__day--keyboard-selected": this.isKeyboardSelected(),
      "react-datepicker__day--range-start": this.isRangeStart(),
      "react-datepicker__day--range-end": this.isRangeEnd(),
      "react-datepicker__day--in-range": this.isInRange(),
      "react-datepicker__day--in-selecting-range": this.isInSelectingRange(),
      "react-datepicker__day--selecting-range-start":
        this.isSelectingRangeStart(),
      "react-datepicker__day--selecting-range-end":
        this.isSelectingRangeEnd(),
      "react-datepicker__day--today": this.isCurrentDay(),
      "react-datepicker__day--weekend": this.isWeekend(),
      "react-datepicker__day--outside-month":
        this.isAfterMonth() || this.isBeforeMonth(),
    },
    this.getHighLightedClass(),
    this.getHolidaysClass(),
  );
};

getAriaLabel = () => {
  const {
    day,
    ariaLabelPrefixWhenEnabled = "Choose",
    ariaLabelPrefixWhenDisabled = "Not available",
  } = this.props;

  const prefix =
    this.isDisabled() || this.isExcluded()
      ? ariaLabelPrefixWhenDisabled
      : ariaLabelPrefixWhenEnabled;

  return `${prefix} ${formatDate(day, "PPPP", this.props.locale)}`;
};

// A function to return the holiday's name as title's content
getTitle = () => {
  const { day, holidays = new Map(), excludeDates } = this.props;
  const compareDt = formatDate(day, "MM.dd.yyyy");
  const titles = [];
  if (holidays.has(compareDt)) {
    titles.push(...holidays.get(compareDt).holidayNames);
  }
  if (this.isExcluded()) {

    const startDate = subDays(day, 1);
    const endDate = newDate(day);
    const container = renderDay(day, { startDate, endDate });
    expect(
      container
        .querySelector(".react-datepicker__day")
        ?.classList.contains(className),
    ).toBe(true);
  });

  it("should not apply the in-range class if start date missing", () => {
    const day = newDate();
    const startDate = subDays(day, 1);
    const container = renderDay(day, { startDate });
    expect(
      container
        .querySelector(".react-datepicker__day")
        ?.classList.contains(className),
    ).toBe(false);
  });

  it("should not apply the in-range class if end date missing", () => {
    const day = newDate();
    const endDate = addDays(day, 1);
    const container = renderDay(day, { endDate });
    expect(
      container
        .querySelector(".react-datepicker__day")
        ?.classList.contains(className),
    ).toBe(false);
  });
});

describe("in selecting range", () => {
  const rangeDayClassName = "react-datepicker__day--in-selecting-range";
  const rangeDayStartClassName =
    "react-datepicker__day--selecting-range-start";
  const rangeDayEndClassName = "react-datepicker__day--selecting-range-end";

  function createDateRange(
    beforeDays: number,
    afterDays: number,
    day = newDate(),
  ) {
    return {
      startDate: subDays(day, beforeDays),
      endDate: addDays(day, afterDays),
      day,
    };
  }

  describe("for a start date picker", () => {
    it("should highlight for dates before the end date", () => {
      const { startDate, endDate } = createDateRange(-1, 1);

      // All these should highlight: today, yesterday (startDate), the day before
      for (let daysFromEnd = 1; daysFromEnd <= 3; daysFromEnd++) {
        const selectingDate = subDays(endDate, daysFromEnd);
        const container = renderDay(selectingDate, {
          startDate,
          endDate,
          selectingDate,
          selectsStart: true,
        });
        expect(
          container
            .querySelector(".react-datepicker__day")
            ?.classList.contains(rangeDayClassName),
        ).toBe(true);
      }
    });

    it("should have a class if it is a start or end date", () => {
      const endDate = newDate();
      const midRangeDate = subDays(endDate, 1);
      const selectingDate = subDays(endDate, 2);

      const containertartDay = renderDay(selectingDate, {
        endDate,
        selectingDate,
        selectsStart: true,
      });
      expect(
        containertartDay
          .querySelector(".react-datepicker__day")
          ?.classList.contains(rangeDayStartClassName),
      ).toBe(true);

      const containerMidRangeDay = renderDay(midRangeDate, {
        endDate,
        selectingDate,
        selectsStart: true,
      });
      expect(
        containerMidRangeDay
          .querySelector(".react-datepicker__day")
          ?.classList.contains(rangeDayStartClassName),
      ).toBe(false);
      expect(
        containerMidRangeDay
          .querySelector(".react-datepicker__day")
          ?.classList.contains(rangeDayStartClassName),
      ).toBe(false);

      const containerEndDay = renderDay(endDate, {
        endDate,
        selectingDate,
        selectsStart: true,
      });
      expect(
        containerEndDay
          .querySelector(".react-datepicker__day")
          ?.classList.contains(rangeDayEndClassName),
      ).toBe(true);
    });

    it("should not highlight for days after the end date", () => {
      const { day, startDate, endDate } = createDateRange(-1, 1);
      const selectingDate = addDays(endDate, 1);
      const container = renderDay(day, {
        startDate,
        endDate,
        selectingDate,
        selectsStart: true,
      });
      expect(
        container
          .querySelector(".react-datepicker__day")
          ?.classList.contains(rangeDayClassName),
      ).toBe(false);
    });

    it("should not highlight if there is no end date selected", () => {
      const startDate = newDate();
      const selectingDate = subDays(startDate, 1);
      const container = renderDay(selectingDate, {
        startDate,
        selectingDate,
        selectsStart: true,
      });
      expect(
        container
          .querySelector(".react-datepicker__day")
